cssCode:
.cloud {
  position: absolute; background: #ffffff;
  border-radius: 50px; opacity: 0.8;
  box-shadow: 0 10px 20px rgba(0,0,0,0.1);
  animation: floatCloud linear infinite;
}
.cloud::before, .cloud::after {
  content: ""; position: absolute; background: #ffffff; border-radius: 50%;
}
.cloud::before { width: 50px; height: 50px; top: -25px; left: 15px; }
.cloud::after { width: 70px; height: 70px; top: -35px; right: 20px; }

@keyframes floatCloud {
  0% { transform: translateX(-150px); }
  100% { transform: translateX(110vw); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;';

const speeds = [15, 25, 35];
const tops = ['20%', '50%', '10%'];

for(let i=0; i<3; i++) {
  const cloud = document.createElement('div');
  cloud.className = 'cloud';
  cloud.style.width = '120px';
  cloud.style.height = '40px';
  cloud.style.top = tops[i];
  cloud.style.animationDuration = `${speeds[i]}s`;
  cloud.style.animationDelay = `${i * -5}s`;
  c.appendChild(cloud);
}
